import{_ as a,o as s,c as o,a2 as n}from"./chunks/framework.BjkiRu3Q.js";const r="/images/admin/pedidos-lista.webp",d="/images/admin/pedido-detalle.webp",h=JSON.parse('{"title":"5. Cómo Atender los Pedidos y Despachar los Paquetes","description":"","frontmatter":{},"headers":[],"relativePath":"admin/pedidos.md","filePath":"admin/pedidos.md"}'),t={name:"admin/pedidos.md"};function i(l,e,p,c,u,m){return s(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="_5-como-atender-los-pedidos-y-despachar-los-paquetes" tabindex="-1">5. Cómo Atender los Pedidos y Despachar los Paquetes <a class="header-anchor" href="#_5-como-atender-los-pedidos-y-despachar-los-paquetes" aria-label="Permalink to &quot;5. Cómo Atender los Pedidos y Despachar los Paquetes&quot;">​</a></h1><p>El módulo de <strong>Pedidos</strong> (<a href="https://pyme.rsfsecure.site/admin/pedidos" target="_blank" rel="noreferrer">https://pyme.rsfsecure.site/admin/pedidos</a>) es donde el equipo de ventas y despacho gestiona el día a día: revisar pagos, preparar pedidos y enviarlos con el mensajero.</p><hr><h2 id="_5-1-lista-general-de-pedidos" tabindex="-1">5.1 Lista General de Pedidos <a class="header-anchor" href="#_5-1-lista-general-de-pedidos" aria-label="Permalink to &quot;5.1 Lista General de Pedidos&quot;">​</a></h2><div class="screenshot-box"><div class="screenshot-header"><div class="screenshot-dots"><span class="screenshot-dot red"></span><span class="screenshot-dot yellow"></span><span class="screenshot-dot green"></span></div><span class="screenshot-title">Listado de Pedidos y Estados de Entrega</span><span class="screenshot-url">https://pyme.rsfsecure.site/admin/pedidos</span></div><div class="screenshot-body"><img src="'+r+`" alt="Listado de Pedidos y Estados de Entrega" loading="lazy" decoding="async"></div></div><hr><h2 id="_5-2-el-ciclo-de-un-pedido-de-la-compra-a-la-entrega" tabindex="-1">5.2 El Ciclo de un Pedido (De la compra a la entrega) <a class="header-anchor" href="#_5-2-el-ciclo-de-un-pedido-de-la-compra-a-la-entrega" aria-label="Permalink to &quot;5.2 El Ciclo de un Pedido (De la compra a la entrega)&quot;">​</a></h2><p>Todos los pedidos avanzan por estas etapas:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ Pendiente de Pago ] ──(Pago Verificado)──&gt; [ Pagado / Confirmado ]</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> (Empacado en Almacén)</span></span>
<span class="line"><span> ▼</span></span>
<span class="line"><span>[ Entregado al Cliente ] &lt;──(Confirmado por Courier)── [ Enviado ] &lt;── [ En Preparación ]</span></span></code></pre></div><hr><h2 id="_5-3-como-procesar-un-pedido-paso-a-paso" tabindex="-1">5.3 Cómo procesar un pedido paso a paso <a class="header-anchor" href="#_5-3-como-procesar-un-pedido-paso-a-paso" aria-label="Permalink to &quot;5.3 Cómo procesar un pedido paso a paso&quot;">​</a></h2><p>Haz clic en cualquier pedido para abrir su detalle (<a href="https://pyme.rsfsecure.site/admin/pedidos/..." target="_blank" rel="noreferrer">https://pyme.rsfsecure.site/admin/pedidos/...</a>):</p><div class="screenshot-box"><div class="screenshot-header"><div class="screenshot-dots"><span class="screenshot-dot red"></span><span class="screenshot-dot yellow"></span><span class="screenshot-dot green"></span></div><span class="screenshot-title">Ficha de Atención del Pedido y Asignación de Guía</span><span class="screenshot-url">https://pyme.rsfsecure.site/admin/pedidos/...</span></div><div class="screenshot-body"><img src="`+d+'" alt="Ficha de Atención del Pedido y Asignación de Guía" loading="lazy" decoding="async"></div></div><h3 id="paso-a-paso-para-atenderlo" tabindex="-1">Paso a paso para atenderlo: <a class="header-anchor" href="#paso-a-paso-para-atenderlo" aria-label="Permalink to &quot;Paso a paso para atenderlo:&quot;">​</a></h3><ol><li><strong>Revisar el Pago:</strong></li></ol><ul><li>Si pagó con <strong>Yappy</strong> o <strong>Tarjeta</strong>, el sistema ya lo marcó automáticamente como <strong>&quot;Pagado&quot;</strong>.</li><li>Si pagó por <strong>Transferencia ACH</strong>, verás la imagen del comprobante bancario que subió el cliente. Revisa en tu banca en línea que el dinero esté disponible y cambia el estado a <strong>&quot;Pagado&quot;</strong>.</li></ul><ol start="2"><li><strong>Empacar los Productos:</strong></li></ol><ul><li>Cambia el estado a <strong>&quot;En Preparación&quot;</strong>.</li><li>El personal de bodega busca los artículos en las estanterías y los empaca de forma segura.</li></ul><ol start="3"><li><strong>Entregar al Mensajero o Transporte:</strong></li></ol><ul><li>Cambia el estado a <strong>&quot;Enviado&quot;</strong>.</li><li>Selecciona la empresa (Servientrega, Uno Express, Mensajero Propio) y escribe el <strong>Número de Guía</strong>.</li><li>Al guardar, el cliente recibirá un mensaje con su número de guía para que pueda rastrear su paquete.</li></ul><ol start="4"><li><strong>Entrega Final:</strong></li></ol><ul><li>Cuando la empresa de transporte o el mensajero confirme la entrega en mano, marca el pedido como <strong>&quot;Entregado&quot;</strong>.</li></ul>',22)])])}const P=a(t,[["render",i]]);export{h as __pageData,P as default};
